// fork of https://www.shadertoy.com/view/l3KfRz

vec4 mainLayer(vec2 u, float tOffset)
{  
    float t = .2*iTime + tOffset, i, j, k;
    vec4 o;
    o.xyz = iResolution;

    u = (u+u-o.xy)/o.y + .15*t;

    vec4 c;
    for (o -= o; i++ < 13.; c += o = sqrt(o*o+.005)) 
    {
        u = 1.3*u*mat2(cos(i*i + vec4(8,19,41,8))) + i - .1*i*t;
        u += .03* exp(cos(t*i+i*i+o.x*4.-4.*u.yx));

        j = 6.5-i;
        k = cos(u.y/j+u.x/i + t)*sin(u.x/i-u.y/j);

        o += pow(k*k, 1.+i+i*cos(i*i+t*i*.4+dot(o+cos(u.y),o-cos(u.x)))) 
            * step(.6*k,o.x) * (1.+cos(vec4(0,1,2,0)+i));

        o = mix(o, length(o)-o.bgra, .2*cos(i*9.*t+i/max(1.,mod(t+.3*i,4.))));

        vec3 chroma = vec3(
            0.7 + 0.4 * cos(k + t * 0.2),
            0.3 + 0.3 * cos(k + t * 0.15),
            0.8 + 0.4 * cos(k + t * 0.1)
        );
        o.rgb *= mix(o.rgb, chroma, 0.15);
    }

    o += .15*c;    
    o = .9-exp(-.4*sqrt(o*o*o));
    o += .2*o*o;  

    o.r *= 0.5;
    o.g *= 0.6;
    o.b *= 1.5;

    o.bg *= tanh(o.r*1.6);
    o += .06*sin(8.*u.x);

    return o;
}

// Exclusion blend mode
vec3 blendExclusion(vec3 base, vec3 blend) {
    return base + blend - 2.0 * base * blend;
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    vec2 uv = fragCoord;

    // Generate three offset layers
    vec4 layer1 = mainLayer(uv, 0.0);
    vec4 layer2 = mainLayer(uv, 2.1); // Phase offset
    vec4 layer3 = mainLayer(uv * 1.2, 4.2); // Scale and phase offset

    // Blend layers using exclusion
    vec3 finalColor = layer1.rgb;
    finalColor = blendExclusion(finalColor, layer2.rgb * 0.8); // Slightly reduced intensity
    finalColor = blendExclusion(finalColor, layer3.rgb * 0.6); // Further reduced intensity

    // Final color adjustments
    finalColor *= 1.2; // Boost overall brightness
    finalColor = pow(finalColor, vec3(0.9)); // Slight gamma adjustment

    // Add subtle pulsing to final result
    float pulse = 1.0 + 0.1 * sin(iTime * 0.15);
    finalColor *= pulse;

    fragColor = vec4(finalColor, 1.0);
}
